INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT128-S2-Q14$batch09$, 128, 2, 14, $batch09$Principle-Conform$batch09$, $batch09$A promise is defined as any agreement that yields an obligation. It is acceptable not to keep one's promise if either the person to whom the promise is made tells the promisor not to keep it, or the promisor is unable to fulfill the obligation due to circumstances beyond the promisor's control.$batch09$, $batch09$Which one of the following is an application of the principle above pertaining to promising?$batch09$, $batch09$B$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=128 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT128-S2-Q14$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$Paul agreed to lend Tom $10. But Paul also owes Maria $10. So it is unacceptable for Paul to fulfill his promise to lend Tom $10 while he still owes Maria money.$batch09$, $batch09$Not an Application$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT128-S2-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$Felicia agreed to tutor Alan in mathematics on Tuesday. However, on his way to the tutorial session, Alan was injured in a car accident and was unable to attend that day. Thus, it was acceptable for Felicia not to tutor Alan in mathematics on Tuesday.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT128-S2-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$Mika agreed to help Owen move on Sunday, but Owen called Mika on the Thursday before the move and asked him to help him move on Saturday instead. So it would be unacceptable for Mika not to consent to help Owen move on Saturday.$batch09$, $batch09$Not an Application$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT128-S2-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$Quinn agreed to water Laura's plants while Laura was out of town. But Laura had forgotten to give Quinn the keys to her place. However, it was unacceptable for Quinn to fail to fulfill his promise to Laura, since Laura did not excuse Quinn from his obligation to water her plants.$batch09$, $batch09$Contradicts the Rule$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT128-S2-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$Ian agreed to pick up Ali at the train station. But Ian decided to stop and return his overdue library books first. As a result, Ian was unable to pick up Ali at the train station. Thus, it was acceptable for Ian to fail to pick up Ali at the train station.$batch09$, $batch09$Misapplies the Rule$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT128-S2-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT128-S2-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Rule$batch09$, $batch09$It's acceptable not to keep a promise if either (1) the person you promised tells you not to keep it, or (2) circumstances beyond your control make you unable to keep it.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$The rule only gives conditions for when breaking a promise is acceptable. It never says when breaking one is unacceptable, and it never says when keeping one is unacceptable. So a correct application should conclude "it was acceptable not to keep it," with one of the two conditions met.$batch09$), (2, $batch09$Goal$batch09$, $batch09$A promise broken because the promisee released the promisor or circumstances beyond the promisor's control prevented it, judged acceptable.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT128-S2-Q14$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$The rule never makes keeping a promise unacceptable, and owing Maria money isn't one of its conditions.$batch09$), ($batch09$B$batch09$, $batch09$Alan was hurt and couldn't come, so Felicia couldn't tutor Alan that Tuesday. That's a circumstance beyond Felicia's control, condition 2, and the conclusion is that not tutoring was acceptable.$batch09$), ($batch09$C$batch09$, $batch09$Owen asked to change the day. The rule says nothing about having to agree to a new request, and it never concludes that anything is unacceptable.$batch09$), ($batch09$D$batch09$, $batch09$Without the keys, Quinn couldn't get in. That's a circumstance beyond Quinn's control, so condition 2 makes not watering acceptable. D only checks condition 1 and reaches the opposite verdict.$batch09$), ($batch09$E$batch09$, $batch09$Ian was unable to make it, but only because Ian chose to return library books first. That was within Ian's control, so condition 2 doesn't apply, and nobody released Ian either.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT128-S2-Q14$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
